import React, { useState, useEffect } from "react";
import axios from "axios";
import Menu from "./Menu";

const TopBar = () => {
  // State for storing index points
  const [nifty, setNifty] = useState(21850.45);
  const [sensex, setSensex] = useState(72150.10);

  // Function to simulate or fetch live data
  useEffect(() => {
    const fetchMarketData = () => {
      // Real API use karne ke liye yahan axios.get('/api/market') ayega
      // Demo ke liye hum values ko thoda random fluctuate kar rahe hain (Live feeling dene ke liye)
      const randomNifty = (21800 + Math.random() * 100).toFixed(2);
      const randomSensex = (72000 + Math.random() * 300).toFixed(2);

      setNifty(randomNifty);
      setSensex(randomSensex);
    };

    // Update every 3 seconds
    const interval = setInterval(fetchMarketData, 3000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="topbar-container">
      <div className="indices-container">
        <div className="nifty">
          <p className="index">NIFTY 50</p>
          <p className="index-points" style={{ color: "#4caf50" }}>{nifty}</p>
          <p className="percent">+0.45%</p>
        </div>
        <div className="sensex">
          <p className="index">SENSEX</p>
          <p className="index-points" style={{ color: "#4caf50" }}>{sensex}</p>
          <p className="percent">+0.38%</p>
        </div>
      </div>

      <Menu />
    </div>
  );
};

export default TopBar;
